#include "stdlib/math/base/special/expf.h"
#include "stdlib/constants/float32/max.h"
#include "stdlib/constants/float32/max_ln.h"
#include "stdlib/constants/float32/min_ln.h"
#include "stdlib/constants/float32/log2_e.h"
#include "stdlib/math/base/special/floorf.h"
#include "stdlib/math/base/special/ldexpf.h"
#include <stdint.h>

static const double LN2_HI = 6.93147180369123816490e-01;
static const double LN2_LO = 1.90821492927058770002e-10;
/* Begin auto-generated functions. The following functions are auto-generated. Do not edit directly. */

// BEGIN: polyval_p

/**
* Evaluates a polynomial.
*
* ## Notes
*
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param x    value at which to evaluate the polynomial
* @return     evaluated polynomial
*/
static float polyval_p( const float x ) {
	return 0.50000001201f + (x * (0.16666665459f + (x * (0.041665795894f + (x * (0.0083334519073f + (x * (0.0013981999507f + (x * 0.000198756915f)))))))));
}

// END: polyval_p

/* End auto-generated functions. */

/**
* Evaluates the natural exponential function of single-precision floating-point numbers.
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_exp( 0.0 );
* // returns 1.0
*/
float stdlib_base_expf( const float x ) {
	float z;
	float g;
	float n;
	if ( x > STDLIB_CONSTANT_FLOAT32_MAX_LN ) {
		return STDLIB_CONSTANT_FLOAT32_MAX;
	}
	if ( x < STDLIB_CONSTANT_FLOAT32_MIN_LN ) {
		return 0.0f;
	}

	// e^x = e^(nln2 + g) = e^(nln2) * e^g = 2^n * e^g.
	z = stdlib_base_floorf( STDLIB_CONSTANT_FLOAT32_LOG2E * x + 0.5f );
	g = x;
	g -= z * LN2_HI;
	g -= z * LN2_LO;
	n = z;
	z = g * g;

	// e^g ≈ 1 + g + g^2 * P(x)
	z = 1.0f + g + z * polyval_p( g );

	return stdlib_base_ldexpf( z, n );
}
